import React, { useState, useCallback, useRef } from 'react';
import Cropper from 'react-easy-crop';

// helper to create blob from cropped area
async function getCroppedImg(imageSrc, pixelCrop) {
  const image = await new Promise((resolve, reject) => {
    const img = new Image();
    img.setAttribute('crossOrigin', 'anonymous');
    img.onload = () => resolve(img);
    img.onerror = (e) => reject(e);
    img.src = imageSrc;
  });

  const canvas = document.createElement('canvas');
  canvas.width = pixelCrop.width;
  canvas.height = pixelCrop.height;
  const ctx = canvas.getContext('2d');

  ctx.drawImage(
    image,
    pixelCrop.x,
    pixelCrop.y,
    pixelCrop.width,
    pixelCrop.height,
    0,
    0,
    pixelCrop.width,
    pixelCrop.height
  );

  return new Promise((resolve) => {
    canvas.toBlob((file) => {
      resolve(file);
    }, 'image/jpeg');
  });
}

export default function ImageUploadCrop({ showId = 'imageUploadCropModal', onUploaded, onClose, aspect = 4/3 }) {
  const [imageSrc, setImageSrc] = useState(null);
  const [crop, setCrop] = useState({ x: 0, y: 0 });
  const [zoom, setZoom] = useState(1);
  const [croppedAreaPixels, setCroppedAreaPixels] = useState(null);
  const [uploading, setUploading] = useState(false);
  const inputRef = useRef(null);

  const onFileChange = async (e) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const url = URL.createObjectURL(file);
      setImageSrc(url);
    }
  };

  const onCropComplete = useCallback((_, croppedAreaPixels) => {
    setCroppedAreaPixels(croppedAreaPixels);
  }, []);

  const doUpload = async () => {
    if (!imageSrc || !croppedAreaPixels) return alert('الرجاء اختيار و اقتصاص الصورة');
    setUploading(true);
    try {
      const blob = await getCroppedImg(imageSrc, croppedAreaPixels);
      const fd = new FormData();
      fd.append('file', blob, 'upload.jpg');

      const res = await fetch('/api/uploads', { method: 'POST', body: fd });
      if (!res.ok) throw new Error('Upload failed');
      const json = await res.json();
      if (onUploaded) onUploaded(json.url);
      // reset
      setImageSrc(null);
      if (inputRef.current) inputRef.current.value = '';
      // close modal via bootstrap data-bs-dismiss button (caller may also close)
    } catch (e) {
      alert('فشل رفع الصورة: ' + (e.message || 'خطأ'));
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="modal fade" id={showId} tabIndex="-1" aria-hidden="true">
      <div className="modal-dialog modal-md modal-dialog-centered">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">رفع و اقتصاص الصورة</h5>
            <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close" onClick={() => { setImageSrc(null); if (onClose) onClose(); }}></button>
          </div>
          <div className="modal-body">
            <div className="mb-3">
              <input ref={inputRef} type="file" accept="image/*" className="form-control" onChange={onFileChange} />
            </div>
            {imageSrc && (
              <div style={{ position: 'relative', width: '100%', height: 400, background: '#333' }}>
                <Cropper
                  image={imageSrc}
                  crop={crop}
                  zoom={zoom}
                  aspect={aspect}
                  onCropChange={setCrop}
                  onZoomChange={setZoom}
                  onCropComplete={onCropComplete}
                />
              </div>
            )}
            {imageSrc && (
              <div className="mt-3">
                <label className="form-label">تكبير</label>
                <input type="range" className="form-range" min={1} max={3} step={0.01} value={zoom} onChange={(e) => setZoom(Number(e.target.value))} />
              </div>
            )}
          </div>
          <div className="modal-footer">
            <button type="button" className="btn btn-secondary" data-bs-dismiss="modal" onClick={() => { setImageSrc(null); if (onClose) onClose(); }}>إغلاق</button>
            <button type="button" className="btn btn-primary" onClick={doUpload} disabled={uploading}>{uploading ? 'جارٍ الرفع...' : 'قص و رفع'}</button>
          </div>
        </div>
      </div>
    </div>
  );
}
